// Fragenpool des Netzbau-Quiz. Allgemeines Fachwissen, keine internen Vorgaben eines Netzbetreibers oder Arbeitgebers.
// Kurzschreibweise: f = Frage, r = richtige Antwort(en), x = falsche Antworten, e = Erklärung.
// Bei r = 'Wahr' oder 'Falsch' und x mit genau einem Eintrag entsteht eine Wahr/Falsch-Frage, bei mehreren r eine Mehrfachauswahl.
import type { Frage, Kategorie, Schema, Stufe } from '../lib/quiz';

interface Eintrag {
  id: string;
  f: string;
  r: string | string[];
  x: string[];
  e: string;
  bild?: Schema;
  quelle?: string;
  ki?: string;
}

function satz(kategorie: Kategorie, stufe: Stufe, eintraege: Eintrag[]): Frage[] {
  return eintraege.map(({ id, f, r, x, e, ...rest }) => {
    const richtig = Array.isArray(r) ? r : [r];
    const wahrFalsch = !Array.isArray(r) && (r === 'Wahr' || r === 'Falsch') && x.length === 1;
    const antworten = wahrFalsch
      ? ['Wahr', 'Falsch'].map((text) => ({ text, richtig: text === r }))
      : [...richtig.map((text) => ({ text, richtig: true })), ...x.map((text) => ({ text, richtig: false }))];
    const typ = wahrFalsch ? 'wahr-falsch' : richtig.length > 1 ? 'mehrfach' : 'einfach';
    return { id, kategorie, stufe, typ, frage: f, antworten, erklaerung: e, ...rest };
  });
}

